using Microsoft.Extensions.Logging;
using Pragmatic.Privacy;

namespace Pragmatic.Logging.Benchmarks.Json;

/// <summary>The JSON comparison's call sites, generated by Pragmatic.</summary>
internal static partial class PragmaticJsonLog
{
    public const string Template = "Order {OrderId} placed by {Customer} for {Amount}";

    [LoggerMessage(EventId = 2001, Level = LogLevel.Information, Message = Template)]
    public static partial void OrderPlaced(ILogger logger, int orderId, string customer, decimal amount);

    [LoggerMessage(EventId = 2002, Level = LogLevel.Information, Message = "Receipt for {OrderId} sent to {Email}")]
    public static partial void ReceiptSent(ILogger logger, int orderId, [PersonalData(DataCategory.Contact)] string email);
}
